const BASE='https://clerky-agent.creativehub254.chatgpt.site/api/zuno/admin';
let token='',verified=false,expires=0,details=null;
try{const saved=JSON.parse(sessionStorage.getItem('zuno-admin-session')||'null');if(saved?.expires>Date.now()){token=saved.token;expires=saved.expires}}catch{}
export const isAdmin=()=>verified&&expires>Date.now();
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(path,body){const r=await fetch(BASE+path,{method:'POST',headers:{'Content-Type':'application/json',...(token?{Authorization:'Bearer '+token}:{})},body:JSON.stringify(body),signal:AbortSignal.timeout(15000)});const d=await r.json();if(!r.ok)throw Object.assign(Error('Admin sign-in could not be completed.'),{code:d.code});return d}
export async function checkAdmin(){if(!token)return false;try{details=await api('/status',{});verified=details.role==='admin';return verified}catch{adminLogout();return false}}
export function adminLogout(){verified=false;token='';expires=0;details=null;try{sessionStorage.removeItem('zuno-admin-session')}catch{}}
export function adminPage(){return isAdmin()?`<section class="mini-panel admin-panel"><span class="eyebrow">PRIVATE ZUNO ADMINISTRATION</span><h1>Welcome back.</h1><p>Signed in as ${esc(details.email)}. All game levels are available for review while this session is active.</p><h2>AI connections</h2><p>Zuno AI, powered by ClerkOps. Paid routes are disabled.</p><div class="admin-routes">${details.routes.map(r=>`<div><strong>${esc(r.provider)}</strong><span>${esc(r.model)}</span></div>`).join('')||'<p>No eligible free connection is available.</p>'}</div><div class="reader-tools"><a class="button" href="/#/play">Review games</a><a class="button light" href="/#/ask">Test Zuno AI</a><button class="chip" data-admin-logout>Sign out</button></div></section>`:`<section class="mini-panel admin-panel"><span class="eyebrow">ZUNO ADMINISTRATION</span><h1>Sign in</h1><p>This area is restricted to the ZUNO administrator.</p><form id="admin-login"><label for="admin-email">Email</label><input id="admin-email" name="email" type="email" autocomplete="username" required><label for="admin-password">Password</label><input id="admin-password" name="password" type="password" autocomplete="current-password" required><button class="button" type="submit">Sign in</button><p id="admin-error" role="status"></p></form></section>`}
export function mountAdmin(render){const form=document.querySelector('#admin-login');if(form)form.addEventListener('submit',async e=>{e.preventDefault();const button=form.querySelector('button');button.disabled=true;const message=document.querySelector('#admin-error');message.textContent='Signing in…';try{const data=await api('/login',{email:form.email.value,password:form.password.value});token=data.token;expires=Date.now()+data.expiresIn*1000;sessionStorage.setItem('zuno-admin-session',JSON.stringify({token,expires}));if(!await checkAdmin())throw Error();render(false)}catch(error){message.textContent=error.code==='LOGIN_LIMIT'?'Too many attempts. Try again in 15 minutes.':'Sign-in failed. Check your email and password, then retry.';button.disabled=false}});document.querySelector('[data-admin-logout]')?.addEventListener('click',()=>{adminLogout();render(false)})}
